values ('ap_chemistry', 7, '7.1', array['7.1']::text[], 'diagram', 'Graphs showing the approach to equilibrium', 'Concentration, partial pressure, or rate versus time graphs used to show how equilibrium is established.', '[{"label": "Concentration or partial pressure vs. time", "meaning": "Reactant and product curves change, then level off to constant values once equilibrium is reached"}, {"label": "Rate vs. time", "meaning": "Forward rate and reverse rate approach each other and become equal at equilibrium"}, {"label": "Constant region", "meaning": "Flat lines indicate no net change, although both processes continue"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u7-r1-003; ced=7.1.A.4 "Graphs of concentration, partial pressure, or rate of reaction versus time"')
