values ('ap_chemistry', 7, '7.2', array['7.2']::text[], 'convention', 'Direction from relative forward and reverse rates', 'Forward rate > reverse rate gives net conversion of reactants to products, reverse rate > forward rate gives net conversion of products to reactants, and equal rates mean equilibrium.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u7-r1-004; ced=7.2.A.1 "An equilibrium state is reached when these rates are equal"')
