values ('ap_chemistry', 7, '7.3', array['7.3', '7.7', '7.10']::text[], 'vocabulary', 'Reaction quotient (Q)', 'Q describes the relative concentrations (or partial pressures) of reaction species at any time and tends toward K, so that Kc = Qc and Kp = Qp at equilibrium.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u7-r1-007; ced=7.3.A.1 "The reaction quotient Qc describes the relative concentrations of reaction species at any time"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 7, '7.5', array['7.5']::text[], 'convention', 'Magnitude of K and extent of reaction', 'A very large K means the reaction proceeds essentially to completion (products dominate at equilibrium); a very small K means it barely proceeds (reactants dominate).', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u7-r1-009; ced=7.5.A.1 "very large K values and proceed essentially to completion. Others have very small K values and barely proceed at all"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
