insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 7, '7.11', array['7.11', '7.12']::text[], 'vocabulary', 'Solubility-product constant (Ksp)', 'Ksp is the equilibrium constant that describes the extent of the reversible dissolution of a salt, and it links Ksp to the salt''s molar solubility in a saturated solution in either direction.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u7-r1-019; ced=7.11.A.1 "The dissolution of a salt is a reversible process whose extent can be described by Ksp"; 7.11.A.4')
