insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 7, '7.12', array['7.12']::text[], 'vocabulary', 'Common-ion effect', 'The solubility of a salt is reduced when it is dissolved in a solution that already contains one of the ions present in the salt.', '[]'::jsonb, NULL, 'Explain it using Le Châtelier''s principle (the added common ion shifts dissolution toward the solid) or calculate it from Ksp, rather than citing a rule of thumb.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-chem-u5-u9-2026-10-10; candidate=ap_chemistry-u7-r1-021; ced=7.12.A.1 "The solubility of a salt is reduced when it is dissolved into a solution that already contains one of the ions present in the salt"')
